/**
 * Expo Config Plugin: DVNT Live Activity (Android only).
 *
 * iOS Live Activities are now generated by expo-widgets (configured in
 * app.config.js). The previous hand-rolled ActivityKit widget-extension /
 * native-module steps (with-live-activity-ios.js + plugins/live-activity-swift/)
 * caused a launch crash and have been removed in favour of expo-widgets.
 * This plugin retains only the Android ongoing-notification path.
 */

const {
  withAndroidLiveNotification,
  withAndroidNotificationFiles,
} = require("./with-live-activity-android");

function withLiveActivity(config) {
  config = withAndroidLiveNotification(config);
  config = withAndroidNotificationFiles(config);
  return config;
}

module.exports = withLiveActivity;
